  {"a": "The Saxons", "p": "Charlemagne fought long wars against which people in north Germany?", "s": "franks", "w": ["The Bavarians", "The Lombards", "The Danes"]},
  {"a": "The Pyrenees", "e": "His last stand became the Song of Roland, one of the oldest poems in French.", "p": "In which mountains did Charlemagne's knight Roland die in battle?", "s": "franks", "w": ["The Carpathians", "The Apennines", "The Alps"]},
  {"a": "Louis the Pious", "p": "Who ruled the Frankish empire after Charlemagne died in 814?", "s": "franks", "w": ["Charles the Bald", "Pepin the Short", "Charles Martel"]},
  {"a": "Writing", "e": "His friend Einhard wrote that he kept writing tablets under his pillow and practised at night.", "p": "Charlemagne learned to read, but which skill did he never master?", "s": "franks", "w": ["Hunting", "Singing", "Riding"]},
  {"a": "The knarr", "e": "It was wider and deeper than a longship, so it could hold sheep, timber and grain.", "p": "Which Viking ship carried cargo rather than warriors?", "s": "vikings", "w": ["The longship", "The galley", "The cog"]},
