  {"a": "Poland's", "e": "They handed their work to Britain and France only weeks before the invasion.", "p": "Whose mathematicians first read Enigma messages before the war began?", "s": "Codes and secrets", "w": ["France's", "Britain's", "Sweden's"]},
  {"a": "Ultra", "p": "What did the Allies call the secret information from broken codes?", "s": "Codes and secrets", "w": ["Magic", "Purple", "Shadow"]},
  {"a": "To fool the Germans", "e": "The trick made Germany expect the landings near Calais instead of Normandy.", "p": "Why did the Allies build rubber tanks and send fake radio messages?", "s": "Codes and secrets", "w": ["To train pilots", "To test weapons", "To cheer troops"]},
  {"a": "The OSS", "p": "What was the American wartime spy service that later became the CIA?", "s": "Codes and secrets", "w": ["The FBI", "The NSA", "The DIA"]},
  {"a": "Sent coded messages", "e": "Their language was used as a code that was never broken.", "p": "What did Navajo speakers do for the United States Marines in the Pacific?", "s": "Codes and secrets", "w": ["Flew scout planes", "Guarded supply depots", "Trained new recruits"]},
  {"a": "Scrap metal", "e": "Iron railings were cut from front gardens and aluminium pots were handed in.", "p": "What did British households collect and give up for the war effort?", "s": "The home front", "w": ["Glass bottles", "Wool blankets", "Old furniture"]},
  {"a": "The Land Army", "p": "Which British women's group worked on the farms during the war?", "s": "The home front", "w": ["The Home Guard", "The Red Cross", "The Girl Guides"]},
  {"a": "War bonds", "p": "What did wartime posters ask Americans to buy to help pay for the war?", "s": "The home front", "w": ["Gold coins", "Farm land", "Bank shares"]},
  {"a": "Dried egg powder", "e": "Tins of dried egg came from America and turned up in almost every recipe.", "p": "What did British cooks use when fresh eggs were hard to find?", "s": "The home front", "w": ["Powdered milk", "Corn starch", "Baking soda"]},
  {"a": "Lend-Lease", "p": "Which American programme sent supplies to Britain and the Soviet Union?", "s": "The home front", "w": ["The New Deal", "The Fair Deal", "The Marshall Plan"]},
  {"a": "Stockings", "e": "Some even drew a line up the back of the leg to look like a seam.", "p": "Which everyday item was so scarce that women painted their legs instead?", "s": "The home front", "w": ["Hairpins", "Umbrellas", "Handbags"]},
  {"a": "To the countryside", "e": "More than a million people were moved in the first days of September 1939.", "p": "Where were many British city children sent when the war began?", "s": "The home front", "w": ["To other cities", "To army camps", "To the coast"]},
  {"a": "The Home Guard", "e": "Its members were mostly men too old or too young for the regular army.", "p": "Which British volunteer force was formed to defend against invasion?", "s": "The Blitz", "w": ["The Civil Defence", "The Territorials", "The Yeomanry"]}
]
$questions$::jsonb)
  with ordinality as question(item, ordinality);

do $validation$
begin
  if (
    select count(*) from public.quiz_questions
    where category_id = 'history' and is_active
  ) <> 2063 then
    raise exception 'History must contain exactly 2063 active questions';
  end if;

  if exists (
    select 1
    from public.quiz_questions as question
    where question.category_id = 'history'
      and (
        cardinality(question.wrong_answers) <> 3
        or (
          select count(distinct lower(trim(answer)))
          from unnest(question.wrong_answers) as answer
        ) <> 3
        or exists (
          select 1
          from unnest(question.wrong_answers) as answer
          where lower(trim(answer)) = lower(trim(question.correct_answer))
        )
      )
  ) then
    raise exception 'History: every question needs 3 distinct wrong answer(s)';
  end if;

  -- Scoped to the rows this migration inserts. The unscoped form also fires on
  -- a duplicate that was already in the bank -- "What was the Hanseatic League?"
  -- sits in both History and Time Traveler and has since August -- which says
  -- nothing about whether this batch is clean.
  if exists (
    select 1
    from public.quiz_questions as proposed
    join public.quiz_questions as existing
      on lower(trim(existing.prompt)) = lower(trim(proposed.prompt))
     and existing.id <> proposed.id
    where proposed.id like 'hist_r2\_%'
  ) then
    raise exception 'History: a new prompt is already used by another question';
  end if;
end;
$validation$;
